   746  /// printPCRelImm - This is used to print an immediate value that ends up
   747  /// being encoded as a pc-relative value.
   748  static void printPCRelImm(MCInst *MI, unsigned OpNo, SStream *O)
   749  {
   750          MCOperand *Op = MCInst_getOperand(MI, OpNo);
   751          if (MCOperand_isImm(Op)) {
   752                  int64_t imm = MCOperand_getImm(Op) + MI->flat_insn->size + MI->address;
   753                  uint8_t opsize = X86_immediate_size(MI->Opcode, NULL);
   754
   755                  // truncat imm for non-64bit
   756                  if (MI->csh->mode != CS_MODE_64) {
   757                          imm = imm & 0xffffffff;
   758                  }
   759
   760                  printImm(MI, O, imm, true);
   761
   762                  if (MI->csh->detail) {
   763  #ifndef CAPSTONE_DIET
   764                          uint8_t access[6];
   765  #endif
   766
   767                          MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].type = X86_OP_IMM;
   768                          // if op_count > 0, then this operand's size is taken from the destination op
   769                          if (MI->flat_insn->detail->x86.op_count > 0)
   770                                  MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size = MI->flat_insn->detail->x86.operands[0].size;
   771                          else if (opsize > 0)
   772                                  MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size = opsize;
   773                          else
   774                                  MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size = MI->imm_size;
   775                          MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].imm = imm;
   776
   777  #ifndef CAPSTONE_DIET
   778                          get_op_access(MI->csh, MCInst_getOpcode(MI), access, &MI->flat_insn->detail->x86.eflags);
   779                          MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].access = access[MI->flat_insn->detail->x86.op_count];
   780  #endif
   781
   782                          MI->flat_insn->detail->x86.op_count++;
   783                  }
   784
   785                  if (MI->op1_size == 0)
   786                          MI->op1_size = MI->imm_size;
   787          }
   788  }
