   790  static void printOperand(MCInst *MI, unsigned OpNo, SStream *O)
   791  {
   792          MCOperand *Op  = MCInst_getOperand(MI, OpNo);
   793
   794          if (MCOperand_isReg(Op)) {
   795                  unsigned int reg = MCOperand_getReg(Op);
   796
   797                  printRegName(O, reg);
   798                  if (MI->csh->detail) {
   799                          if (MI->csh->doing_mem) {
   800                                  MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.base = X86_register_map(reg);
   801                          } else {
   802  #ifndef CAPSTONE_DIET
   803                                  uint8_t access[6];
   804  #endif
   805
   806                                  MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].type = X86_OP_REG;
   807                                  MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].reg = X86_register_map(reg);
   808                                  MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size = MI->csh->regsize_map[X86_register_map(reg)];
   809
   810  #ifndef CAPSTONE_DIET
   811                                  get_op_access(MI->csh, MCInst_getOpcode(MI), access, &MI->flat_insn->detail->x86.eflags);
   812                                  MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].access = access[MI->flat_insn->detail->x86.op_count];
   813  #endif
   814
   815                                  MI->flat_insn->detail->x86.op_count++;
   816                          }
   817                  }
   818
   819                  if (MI->op1_size == 0)
   820                          MI->op1_size = MI->csh->regsize_map[X86_register_map(reg)];
   821          } else if (MCOperand_isImm(Op)) {
   822                  uint8_t encsize;
   823                  int64_t imm = MCOperand_getImm(Op);
   824                  uint8_t opsize = X86_immediate_size(MCInst_getOpcode(MI), &encsize);
   825
   826                  if (opsize == 1)    // print 1 byte immediate in positive form
   827                          imm = imm & 0xff;
   828
   829                  // printf(">>> id = %u\n", MI->flat_insn->id);
   830                  switch(MI->flat_insn->id) {
   831                          default:
   832                                  printImm(MI, O, imm, MI->csh->imm_unsigned);
   833                                  break;
   834
   835                          case X86_INS_MOVABS:
   836                          case X86_INS_MOV:
   837                                  // do not print number in negative form
   838                                  printImm(MI, O, imm, true);
   839                                  break;
   840
   841                          case X86_INS_IN:
   842                          case X86_INS_OUT:
   843                          case X86_INS_INT:
   844                                  // do not print number in negative form
   845                                  imm = imm & 0xff;
   846                                  printImm(MI, O, imm, true);
   847                                  break;
   848
   849                          case X86_INS_LCALL:
   850                          case X86_INS_LJMP:
   851                          case X86_INS_JMP:
   852                                  // always print address in positive form
   853                                  if (OpNo == 1) {      // ptr16 part
   854                                          imm = imm & 0xffff;
   855                                          opsize = 2;
   856                                  } else
   857                                          opsize = 4;
   858                                  printImm(MI, O, imm, true);
   859                                  break;
   860
   861                          case X86_INS_AND:
   862                          case X86_INS_OR:
   863                          case X86_INS_XOR:
   864                                  // do not print number in negative form
   865                                  if (imm >= 0 && imm <= HEX_THRESHOLD)
   866                                          printImm(MI, O, imm, true);
   867                                  else {
   868                                          imm = arch_masks[opsize? opsize : MI->imm_size] & imm;
   869                                          printImm(MI, O, imm, true);
   870                                  }
   871                                  break;
   872
   873                          case X86_INS_RET:
   874                          case X86_INS_RETF:
   875                                  // RET imm16
   876                                  if (imm >= 0 && imm <= HEX_THRESHOLD)
   877                                          printImm(MI, O, imm, true);
   878                                  else {
   879                                          imm = 0xffff & imm;
   880                                          printImm(MI, O, imm, true);
   881                                  }
   882                                  break;
   883                  }
   884
   885                  if (MI->csh->detail) {
   886                          if (MI->csh->doing_mem) {
   887                                  MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.disp = imm;
   888                          } else {
   889  #ifndef CAPSTONE_DIET
   890                                  uint8_t access[6];
   891  #endif
   892
   893                                  MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].type = X86_OP_IMM;
   894                                  if (opsize > 0) {
   895                                          MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size = opsize;
   896                                          MI->flat_insn->detail->x86.encoding.imm_size = encsize;
   897                                  } else if (MI->flat_insn->detail->x86.op_count > 0) {
   898                                          if (MI->flat_insn->id != X86_INS_LCALL && MI->flat_insn->id != X86_INS_LJMP) {
   899                                                  MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size =
   900                                                        MI->flat_insn->detail->x86.operands[0].size;
   901                                          } else
   902                                                  MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size = MI->imm_size;
   903                                  } else
   904                                          MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size = MI->imm_size;
   905                                  MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].imm = imm;
   906
   907  #ifndef CAPSTONE_DIET
   908                                  get_op_access(MI->csh, MCInst_getOpcode(MI), access, &MI->flat_insn->detail->x86.eflags);
   909                                  MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].access = access[MI->flat_insn->detail->x86.op_count];
   910  #endif
   911
   912                                  MI->flat_insn->detail->x86.op_count++;
   913                          }
   914                  }
   915          }
   916  }
