   918  static void printMemReference(MCInst *MI, unsigned Op, SStream *O)
   919  {
   920          bool NeedPlus = false;
   921          MCOperand *BaseReg  = MCInst_getOperand(MI, Op + X86_AddrBaseReg);
   922          uint64_t ScaleVal = MCOperand_getImm(MCInst_getOperand(MI, Op + X86_AddrScaleAmt));
   923          MCOperand *IndexReg  = MCInst_getOperand(MI, Op + X86_AddrIndexReg);
   924          MCOperand *DispSpec = MCInst_getOperand(MI, Op + X86_AddrDisp);
   925          MCOperand *SegReg = MCInst_getOperand(MI, Op + X86_AddrSegmentReg);
   926          int reg;
   927
   928          if (MI->csh->detail) {
   929  #ifndef CAPSTONE_DIET
   930                  uint8_t access[6];
   931  #endif
   932
   933                  MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].type = X86_OP_MEM;
   934                  MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size = MI->x86opsize;
   935                  MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.segment = X86_REG_INVALID;
   936                  MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.base = X86_register_map(MCOperand_getReg(BaseReg));
   937          if (MCOperand_getReg(IndexReg) != X86_EIZ) {
   938              MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.index = X86_register_map(MCOperand_getReg(IndexReg));
   939          }
   940                  MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.scale = (int)ScaleVal;
   941                  MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.disp = 0;
   942
   943  #ifndef CAPSTONE_DIET
   944                  get_op_access(MI->csh, MCInst_getOpcode(MI), access, &MI->flat_insn->detail->x86.eflags);
   945                  MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].access = access[MI->flat_insn->detail->x86.op_count];
   946  #endif
   947          }
   948
   949          // If this has a segment register, print it.
   950          reg = MCOperand_getReg(SegReg);
   951          if (reg) {
   952                  _printOperand(MI, Op + X86_AddrSegmentReg, O);
   953                  if (MI->csh->detail) {
   954                          MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.segment = X86_register_map(reg);
   955                  }
   956                  SStream_concat0(O, ":");
   957          }
   958
   959          SStream_concat0(O, "[");
   960
   961          if (MCOperand_getReg(BaseReg)) {
   962                  _printOperand(MI, Op + X86_AddrBaseReg, O);
   963                  NeedPlus = true;
   964          }
   965
   966          if (MCOperand_getReg(IndexReg) && MCOperand_getReg(IndexReg) != X86_EIZ) {
   967                  if (NeedPlus) SStream_concat0(O, " + ");
   968                  _printOperand(MI, Op + X86_AddrIndexReg, O);
   969                  if (ScaleVal != 1)
   970                          SStream_concat(O, "*%u", ScaleVal);
   971                  NeedPlus = true;
   972          }
   973
   974          if (MCOperand_isImm(DispSpec)) {
   975                  int64_t DispVal = MCOperand_getImm(DispSpec);
   976                  if (MI->csh->detail)
   977                          MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.disp = DispVal;
   978                  if (DispVal) {
   979                          if (NeedPlus) {
   980                                  if (DispVal < 0) {
   981                                          SStream_concat0(O, " - ");
   982                                          printImm(MI, O, -DispVal, true);
   983                                  } else {
   984                                          SStream_concat0(O, " + ");
   985                                          printImm(MI, O, DispVal, true);
   986                                  }
   987                          } else {
   988                                  // memory reference to an immediate address
   989                                  if (MI->csh->mode == CS_MODE_64)
   990                                          MI->op1_size = 8;
   991                                  if (DispVal < 0) {
   992                                          printImm(MI, O, arch_masks[MI->csh->mode] & DispVal, true);
   993                                  } else {
   994                                          printImm(MI, O, DispVal, true);
   995                                  }
   996                          }
   997
   998                  } else {
   999                          // DispVal = 0
  1000                          if (!NeedPlus)  // [0]
  1001                                  SStream_concat0(O, "0");
  1002                  }
  1003          }
  1004
  1005          SStream_concat0(O, "]");
  1006
  1007          if (MI->csh->detail)
  1008                  MI->flat_insn->detail->x86.op_count++;
  1009
  1010          if (MI->op1_size == 0)
